mapper.select:
SELECT
WHERE t.deleted = 0
ORDER BY t.service_date DESC, t.id DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE volunteer_record
status = #{toStatus}, review_user_id = #{reviewUserId}, review_time = NOW(), reject_reason = #{rejectReason}, updated_at = NOW()
WHERE id = #{id} AND deleted = 0 AND status = #{fromStatus}

UPDATE volunteer_record
project_id = #{r.projectId}, service_date = #{r.serviceDate}, sign_in = #{r.signIn}, sign_out = #{r.signOut}, hours = #{r.hours}, hour_type = #{r.hourType}, source = #{r.source}, recorder_id = #{r.recorderId}, recorder_subject = #{r.recorderSubject}, status = #{r.status}, review_user_id = #{r.reviewUserId}, review_time = #{r.reviewTime}, reject_reason = #{r.rejectReason}, makeup_note = #{r.makeupNote}, updated_at = NOW()
WHERE id = #{r.id} AND deleted = 0 AND status = #{fromStatus}

mapper.select:
SELECT COALESCE(SUM(t.hours), 0)
FROM volunteer_record t
WHERE t.user_id = #{userId}
  AND t.deleted = 0
  AND t.status = 'approved'
AND t.hour_type = #{hourType}
AND t.service_date >= #{startDate}
AND t.service_date <= #{endDate}

SELECT COALESCE(SUM(t.hours), 0)
FROM volunteer_record t
WHERE t.user_id = #{userId}
  AND t.service_date = #{serviceDate}
  AND t.deleted = 0
  AND t.status = 'approved'

SELECT COUNT(*)
FROM volunteer_record t
WHERE t.user_id = #{userId}
  AND t.service_date = #{serviceDate}
  AND t.deleted = 0
